#!/usr/bin/env python3
"""Strip (* *) comments, blank lines, and the verification-only definitions
from a Fortress .fss file.  One rule, applied identically to every file it is
pointed at, so before/after counts are comparable.

Excluded as verification-only: initW, goldRow, goldRows, goldMat, goldHeads,
goldenCheck (definitions) and the bare `goldenCheck()` call.
"""
import re, sys

EXCLUDE = {"initW", "goldRow", "goldRows", "goldMat", "goldHeads", "goldenCheck"}


def strip_comments(src):
    out, depth, i = [], 0, 0
    while i < len(src):
        if src.startswith("(*", i):
            depth += 1
            i += 2
        elif src.startswith("*)", i) and depth:
            depth -= 1
            i += 2
        else:
            if not depth:
                out.append(src[i])
            i += 1
    return "".join(out)


